/* * rename() for C News on OS-9 -- written for this collection, 2026-09-23. * * newsrun moves a batch relaynews refused into bad/ with rename().  The * only rename a link line could reach was blarslib's, which sits in ln.c * beside the raw-sector link() that linkcopy.c replaces, and the two could * not be linked together.  This one is linkcopy's link() -- an exclusive * create and a copy -- followed by removing the old name, so it also works * between directories, which is the move newsrun makes. * * Returns 0, or -1 with errno set; on failure the old name is left alone. */extern int link(), unlink();intrename(from, to)char *from, *to;{	if (link(from, to) < 0)		return -1;	return unlink(from);}